"""Write the Scopus and Web of Science results into the RESS manuscript. Run after patch_extra16_ress.py."""
from pathlib import Path
p=Path("submission-ress/manuscript.tex");T=p.read_text()
R=[("These studies answer different questions with different labels, and our results do not replicate or refute any of them. In the sources we searched through 7 November 2026, which did not include Scopus or Web of Science, we found no MetroPT study that reports probability calibration across horizons with every failure held out.",
"Database searches found evaluations closer to ours. Marmoucha et al.\\ \\cite{marmoucha2026} train on one failure, tune on the next and test on a third, with a 2-hour precursor label and active failure periods excluded. Three of their four models caught none of 240 positive records, and XGBoost caught one. They conclude that the features and labels may not support reliable detection under strict chronological evaluation. Kulkarni and Digalwar \\cite{kulkarni2026} use two rolling folds with each test failure unseen and report that both failures are detected, with detection depending on the training cut-off. Their positive rows lie inside the failure windows, so this is detection rather than warning. Other papers report lead time: the abstracts of Chakri et al.\\ \\cite{chakri2026} give 17 to 42 minutes before the four events, and those of Alhammadi et al.\\ \\cite{alhammadi2025} and Silva et al.\\ \\cite{silva2023} give up to two hours. We read only the abstracts of these three, so we cannot say how their windows or thresholds were set.\n\nApart from the agreement with Marmoucha et al., these studies answer different questions with different labels, and our results do not replicate or refute any of them. In Scopus, Web of Science and the other sources we searched through 7 November 2026, we found no MetroPT study that reports probability calibration across horizons with every failure held out. A search of titles, abstracts, keywords and references cannot detect a paper that does this without saying so there."),
("Toribio et al.\\ \\cite{toribio2026} & Forecast, then detection &","Marmoucha et al.\\ \\cite{marmoucha2026} & Supervised risk & Chronological blocks & 1 & 2 h & None seen\\\\\nKulkarni and Digalwar \\cite{kulkarni2026} & Cost-aware detection & Rolling folds & 2 & None & Thresholds only\\\\\nToribio et al.\\ \\cite{toribio2026} & Forecast, then detection &"),
("so the failure is one of transfer rather than of fit.","so the failure is one of transfer rather than of fit. Marmoucha et al.\\ \\cite{marmoucha2026} found almost no detection on their one chronological test failure, which is independent support in the same direction."),
("Sources for related work exclude Scopus and Web of Science.","The related-work search covered titles, abstracts, keywords and references, and we read some close conference papers in abstract only."),
]
for a,b in R:
    assert T.count(a)==1,a
    T=T.replace(a,b)
p.write_text(T);print(len(R),"replacements")
